// ─── File: src/main/java/com/bank/errorexc/service/ErrorVsExceptionService.java ───
package com.bank.errorexc.service;

public class ErrorVsExceptionService {

    // ═══ ERROR: StackOverflowError — infinite recursion ═══
    public int infiniteRecursion(int n) {
        return infiniteRecursion(n + 1);  // never stops → StackOverflowError!
    }

    // ═══ EXCEPTION: recoverable application error ═══
    public int safeDivide(int a, int b) {
        if (b == 0) throw new ArithmeticException("Division by zero!");
        return a / b;
    }

    // ═══ BAD: catching Throwable hides Errors ═══
    public String badCatchAll(Runnable task) {
        try {
            task.run();
            return "success";
        } catch (Throwable t) {  // (Avoid) catches EVERYTHING including OOM, StackOverflow!
            return "swallowed: " + t.getClass().getSimpleName();
        }
    }

    // ═══ GOOD: catching specific Exception only ═══
    public String goodCatch(Runnable task) {
        try {
            task.run();
            return "success";
        } catch (Exception e) {  // (Recommended) catches Exceptions only — Errors propagate!
            return "handled: " + e.getClass().getSimpleName();
        }
    }
}
```

```java
// ─── File: src/test/java/com/bank/errorexc/ErrorVsExceptionTest.java ───
package com.bank.errorexc;

import com.bank.errorexc.service.ErrorVsExceptionService;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ErrorVsExceptionTest {

    ErrorVsExceptionService service = new ErrorVsExceptionService();

    @Test
    void error_isUnchecked() {
        assertThat(Throwable.class.isAssignableFrom(Error.class)).isTrue();
        assertThat(Exception.class.isAssignableFrom(Error.class)).isFalse();
        // Error extends Throwable, NOT Exception!
    }

    @Test
    void stackOverflow_isAnError() {
        assertThatThrownBy(() -> service.infiniteRecursion(0))
            .isInstanceOf(StackOverflowError.class);
        // StackOverflowError extends Error — JVM problem!
    }

    @Test
    void arithmeticException_isAnException() {
        assertThatThrownBy(() -> service.safeDivide(10, 0))
            .isInstanceOf(ArithmeticException.class);
        // ArithmeticException extends RuntimeException extends Exception
    }

    @Test
    void badCatchAll_swallowsError() {
        String result = service.badCatchAll(() -> service.infiniteRecursion(0));
        assertThat(result).isEqualTo("swallowed: StackOverflowError");
        // (Avoid) Error was SWALLOWED! JVM problem hidden. Processing continues in bad state!
    }

    @Test
    void goodCatch_letsErrorPropagate() {
        assertThatThrownBy(() -> service.goodCatch(() -> service.infiniteRecursion(0)))
            .isInstanceOf(StackOverflowError.class);
        // (Recommended) Error PROPAGATES! JVM crashes cleanly. No corrupted state.
    }

    @Test
    void goodCatch_handlesException() {
        String result = service.goodCatch(() -> service.safeDivide(10, 0));
        assertThat(result).isEqualTo("handled: ArithmeticException");
        // (Recommended) Exception caught and handled. Error would propagate.
    }

    @Test
    void hierarchy() {
        // Error: NOT recoverable. Don't catch.
        assertThat(Error.class.getSuperclass()).isEqualTo(Throwable.class);
        // Exception: recoverable. Catch and handle.
        assertThat(Exception.class.getSuperclass()).isEqualTo(Throwable.class);
        // RuntimeException: unchecked Exception.
        assertThat(RuntimeException.class.getSuperclass()).isEqualTo(Exception.class);
    }
}
